#!/usr/bin/env python3
# genspvinc.py <out.inc> <name>=<file.spv>...: the SPIR-V of the frame generation passes as C++ arrays, with each pass's
# descriptor bindings (read from the module) and its workgroup size.
#
# SPDX-License-Identifier: GPL-3.0-or-later
import sys, os
sys.path.insert(0, os.path.dirname(__file__))
from spvrefl import parse
import struct

TYPES = {'sampled_image': 'VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE', 'storage_image': 'VK_DESCRIPTOR_TYPE_STORAGE_IMAGE',
         'uniform_buffer': 'VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER_DYNAMIC', 'storage_buffer': 'VK_DESCRIPTOR_TYPE_STORAGE_BUFFER',
         'sampler': 'VK_DESCRIPTOR_TYPE_SAMPLER'}

def block_names(path):
    # uniform blocks have empty variable names; their struct type names (cbOF, cbOF_SPD, cbFI) say which they are
    w = open(path, 'rb').read(); words = struct.unpack('<%dI' % (len(w) // 4), w)
    i = 5; names = {}; ptrs = {}; vars_ = {}
    while i < len(words):
        op = words[i] & 0xffff; n = words[i] >> 16; a = words[i+1:i+n]
        if op == 5: names[a[0]] = struct.pack('<%dI' % (n - 2), *a[1:]).split(b'\0')[0].decode()
        elif op == 32: ptrs[a[0]] = a[2]
        elif op == 59: vars_[a[1]] = a[0]
        i += n
    return {vid: names.get(ptrs.get(pt), '?') for vid, pt in vars_.items()}

out = open(sys.argv[1], 'w', newline='\n')
out.write('// Generated by tools/build-shaders.sh: do not edit. AMD FidelityFX SDK 2.3.0 frame generation passes (MIT, see\n'
          '// shaders/LICENSE.txt), compiled from HLSL to SPIR-V by glslang (optical flow only: FFX_FG_OF_ONLY).\n\n')
entries = []
for arg in sys.argv[2:]:
    name, path = arg.split('=', 1)
    binds, local = parse(path)
    bnames = None
    words = open(path, 'rb').read()
    count = len(words) // 4
    vals = struct.unpack('<%dI' % count, words)
    out.write('static const u32 k_fg_spv_%s[%d] = {\n' % (name, count))
    for j in range(0, count, 12):
        out.write('\t' + ', '.join('0x%08x' % v for v in vals[j:j+12]) + ',\n')
    out.write('};\n')
    rows = []
    for s, b, kind, nm, fmt in binds:
        assert s == 0, (name, nm)
        if kind == 'uniform_buffer' and not nm:
            nm = 'cbOF_SPD' if b == 201 else ('cbFI' if name.startswith('fi_') else 'cbOF')
        rows.append('\t{%d, %s, "%s"},' % (b, TYPES[kind], nm))
    out.write('static const fg_binding k_fg_bind_%s[%d] = {\n%s\n};\n\n' % (name, len(rows), '\n'.join(rows)))
    entries.append((name, count, local, len(rows)))
out.write('static const fg_shader k_fg_shaders[%d] = {\n' % len(entries))
for name, count, local, nb in entries:
    out.write('\t{"%s", k_fg_spv_%s, %d, {%d, %d, %d}, k_fg_bind_%s, %d},\n' % (name, name, count, local[0], local[1], local[2], name, nb))
out.write('};\n')
print('wrote', sys.argv[1], len(entries), 'shaders')
